------------ import ------------
------------ import ------------

------------ define ------------
local GoodNodeMBPath = "Game.Behaviours.GoodNodeMB"
------------ define ------------

--- from: Assets/BundleResources/Prefabs/OnlineReward/OnlineRewardCell.prefab > name: OnlineRewardCell
---@class OnlineRewardCell
---@field Env                            OnlineRewardCell
---@field controller                        Engine.Modules.LuaBehaviour
---@field Progress                        UnityEngine.RectTransform                @ 0
---@field ImgStar                        UnityEngine.RectTransform                @ 1
---@field BtnNode                        UnityEngine.RectTransform                @ 2
---@field TextToday                        CustomText                                @ 3
---@field TextNextDay                    CustomText                                @ 4
---@field GoodNode                        UnityEngine.RectTransform                @ 5
---@field StatusFinish                    UnityEngine.RectTransform                @ 6
local OnlineRewardCell = Class('OnlineRewardCell')

function OnlineRewardCell:__init()
    self.data = nil
    self.cb = nil
end

function OnlineRewardCell:__delete()
    self.data = nil
    self.cb = nil
end

function OnlineRewardCell:Awake()
    SetButtonAction(self.BtnNode, function()
        ---点击的事件的逻辑
        self:OnButtonAction(self.data)
    end)
end

function OnlineRewardCell:OnButtonAction(data)
    local status = checkNumber(self.data.status)
    local rewardType = checkNumber(self.data.type)
    if rewardType == 2 then
        ---大奖状态
        if status == 1 then
            ---可领取
            self.cb(data)
        else
            local goodsDojo = table.takeFirst(self.data.rewards)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsDojo.goodsId)
            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end
    else
        local t = checkNumber(self.data.targetNum) - checkNumber(self.data.progress)
        t = math.max(0, t)
        if status == 1 or (t <= 0 and status ~= 2) then
            --可领取的状态
            self.cb(data)
        else
            local goodsDojo = table.takeFirst(self.data.rewards)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsDojo.goodsId)
            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end
    end
end

function OnlineRewardCell:FreshUI(data, cb)
    self.data = data
    self.cb = cb
    CfUtils.SetActive(self.TextToday, checkNumber(data.type) == 1)
    CfUtils.SetActive(self.TextNextDay, checkNumber(data.type) == 2)
    CfUtils.SetActive(self.StatusFinish, checkNumber(data.status) > 1)
    ---已领取的逻辑
    ---@type GoodNodeMB
    local goodNodesEnv = CfUtils.GetLuaScr(self.GoodNode, GoodNodeMBPath)
    if not isNull(goodNodesEnv) then
        local goodsDojo = table.takeFirst(data.rewards)
        goodNodesEnv:Reload({ goodsId = goodsDojo.goodsId,
                              isShowNo = true, text = 'x' .. tostring(goodsDojo.num)
        })
        goodNodesEnv:SetClickButtonAction(function()
            self:OnButtonAction(self.data)
            --local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsDojo.goodsId)
            --GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end)
    end
    CfUtils.SetUISwitchImage(self.Progress.transform:Find("ImgStar"), checkNumber(data.status) > 1 and 2 or 1)
    if checkNumber(data.type) == 1 then
        CfUtils.FillText(self.TextToday, CfUtils.GetTimeHumanize(data.targetNum))
    end
    local status = checkNumber(data.status)
    local rewardType = checkNumber(data.type)
    if rewardType == 2 then
        ---大奖状态
        CfUtils.SetActive(self.TextNextDay, status ~= 1)
        CfUtils.SetActive(self.BtnNode:Find("StatusGet"), status == 1) --可领取的状态
    else
        local t = checkNumber(data.targetNum) - checkNumber(data.progress)
        t = math.max(0, t)
        if status == 1 or (t <= 0 and status ~= 2) then
            --可领取的状态
            CfUtils.SetActive(self.TextToday, false)
            CfUtils.SetActive(self.BtnNode:Find("StatusGet"), true)
        else
            CfUtils.SetActive(self.TextToday, true)
            CfUtils.SetActive(self.BtnNode:Find("StatusGet"), false)
        end
    end
end

function OnlineRewardCell:SetLineActive(active, isFinalNode)
    CfUtils.SetActive(self.Progress.transform:Find("ImgLine"), checkBool(active))
    CfUtils.SetActive(self.Progress.transform:Find('ImgLineR'), checkBool(isFinalNode))
end

function OnlineRewardCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return OnlineRewardCell